SELECT COALESCE(SUM(total_hours), 0)
FROM attendance_records
WHERE worker_id = #{workerId}
  AND check_in_time >= #{startTime}
  AND check_in_time < #{endTime}

SELECT COUNT(DISTINCT DATE(check_in_time))
FROM attendance_records
WHERE worker_id = #{workerId}
  AND check_in_time >= #{startTime}
  AND check_in_time < #{endTime}
